public int LengthOfLongestSubstringBrute(string s)
{
    int best = 0;

    for (int i = 0; i < s.Length; i++)
    {
        var seen = new HashSet<char>();
        for (int j = i; j < s.Length; j++)
        {
            if (!seen.Add(s[j])) break;
            best = Math.Max(best, j - i + 1);
        }
    }

    return best;
}

public int LengthOfLongestSubstring(string s)
{
    var window = new HashSet<char>();
    int left = 0;
    int best = 0;

    for (int right = 0; right < s.Length; right++)
    {
        // Shrink until s[right] can be added safely
        while (window.Contains(s[right]))
        {
            window.Remove(s[left]);
            left++;
        }

        window.Add(s[right]);
        best = Math.Max(best, right - left + 1);
    }

    return best;
}

public int LengthOfLongestSubstringIndex(string s)
{
    // ASCII assumption; use a Dictionary<char,int> for full Unicode
    var lastSeen = new int[128];
    Array.Fill(lastSeen, -1);

    int left = 0;
    int best = 0;

    for (int right = 0; right < s.Length; right++)
    {
        char c = s[right];

        // Move left past the previous occurrence if it is inside the window
        if (lastSeen[c] >= left)
        {
            left = lastSeen[c] + 1;
        }

        lastSeen[c] = right;
        best = Math.Max(best, right - left + 1);
    }

    return best;
}

public int LengthOfLongestSubstring(string s)
{
    var lastSeen = new Dictionary<char, int>();
    int left = 0;
    int best = 0;

    for (int right = 0; right < s.Length; right++)
    {
        char c = s[right];
        if (lastSeen.TryGetValue(c, out int prev) && prev >= left)
        {
            left = prev + 1;
        }

        lastSeen[c] = right;
        best = Math.Max(best, right - left + 1);
    }

    return best;
}
